import {createHash} from 'node:crypto';
import {readFileSync,realpathSync,statSync} from 'node:fs';
import {tmpdir} from 'node:os';
import {basename,dirname,isAbsolute} from 'node:path';

// Only workbooks generated by the owned CLR fixture, never Downloads/originals.
export function readOwnedHistoryWorkbook(path,hash){
 const reject=()=>{throw Error('history_test_policy_source_hash');};
 if(typeof path!=='string'||typeof hash!=='string'||!/^[0-9a-f]{64}$/.test(hash)||!isAbsolute(path))return reject();
 const output=dirname(path),fixture=dirname(output);
 if(realpathSync(path)!==path||dirname(fixture)!==realpathSync(tmpdir())||!/^W7HC\.[0-9a-f]{32}$/.test(basename(fixture))||basename(output)!=='output'
  ||!/^(?:new-[0-9a-f]{32}|corrected-legacy)\.xlsx$/.test(basename(path)))return reject();
 const info=statSync(path);if(!info.isFile()||info.size<1||info.size>20971520)throw Error('history_test_policy_source_bytes');
 const bytes=readFileSync(path);if(createHash('sha256').update(bytes).digest('hex')!==hash)throw Error('history_test_policy_source_bytes');
 return bytes;
}
